package es.aelb.backendweb.infrastructure.email;
import es.aelb.backendweb.application.email.*; import es.aelb.backendweb.infrastructure.config.EmailProperties; import org.springframework.stereotype.Component; import org.springframework.context.annotation.Profile; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import software.amazon.awssdk.regions.Region; import software.amazon.awssdk.services.ses.SesClient; import software.amazon.awssdk.services.ses.model.*;
@Component("sesEmailSender") @Profile("prod")
public class SesEmailSender implements EmailSender {
 private static final Logger log = LoggerFactory.getLogger(SesEmailSender.class);
 private final SesClient ses; private final EmailProperties props;
 public SesEmailSender(EmailProperties props){this.props=props; if("local".equalsIgnoreCase(props.getAppEnv())||!"ses".equalsIgnoreCase(props.getProvider())) throw new IllegalStateException("SES no puede inicializarse en entorno local/no SES"); this.ses=SesClient.builder().region(Region.of(props.getSesRegion())).build();}
 public void send(EmailMessage m){try{ses.sendEmail(SendEmailRequest.builder().source(source()).destination(Destination.builder().toAddresses(m.recipient()).build()).message(Message.builder().subject(Content.builder().data(m.subject()).charset("UTF-8").build()).body(Body.builder().text(Content.builder().data(m.plainText()).charset("UTF-8").build()).html(Content.builder().data(m.html()).charset("UTF-8").build()).build()).build()).build());}catch(SesException e){int status=e.statusCode(); String errorCode=e.awsErrorDetails()!=null?String.valueOf(e.awsErrorDetails().errorCode()):"unknown"; log.warn("event=SES_SEND_FAILED statusCode={} errorCode={} requestId={}",status,errorCode,e.requestId()); if(status==400 && e.awsErrorDetails()!=null && String.valueOf(e.awsErrorDetails().errorCode()).toLowerCase().contains("throttl")) throw new TemporaryEmailException("SES throttling",e); if(status>=500)throw new TemporaryEmailException("SES temporalmente no disponible",e); throw new PermanentEmailException("SES rechazó el email",e);}catch(RuntimeException e){log.warn("event=SES_SEND_FAILED errorType={} error={}",e.getClass().getSimpleName(),e.getMessage());throw new TemporaryEmailException("Error de red con SES",e);}}
 // "Nombre" <direccion> codificado en RFC 2047 para que el remitente se muestre con el nombre de la asociación.
 private String source(){try{return props.getFromName()==null||props.getFromName().isBlank()?props.getFrom():new jakarta.mail.internet.InternetAddress(props.getFrom(),props.getFromName(),"UTF-8").toString();}catch(java.io.UnsupportedEncodingException e){return props.getFrom();}}
}
